#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: temporary owner-operated laptop demo host. The OCI profile remains
# canonical and unchanged; this script is a separate, reversible adapter.
# ──────────────────────────────────────────────────────────────────────────

if [[ "$-" == *x* ]]; then
  set +x
  printf 'Refusing to run with shell tracing: xtrace can expose database and DNS secrets.\n' >&2
  exit 1
fi

TOTAL_STAGES=7
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(git -C "$SCRIPT_DIR" rev-parse --show-toplevel 2>/dev/null || true)"
[[ -n "$REPO_ROOT" ]] || { warn "Run this wizard from inside the Nebula repository."; exit 1; }
FRONTEND_DIR="$REPO_ROOT/frontend"
OCI_COMPOSE="$REPO_ROOT/deploy/oci/compose.yaml"
EVIDENCE_DIR="$REPO_ROOT/docs/evidence"
EVIDENCE_FILE="$EVIDENCE_DIR/BE002_OWNER_OPERATED_DEMO_EVIDENCE.md"
COMPOSE_PROJECT="nebula-owner-demo"
USER_CONFIG_HOME="${XDG_CONFIG_HOME:-"$HOME/.config"}"
RUNTIME_DIR="$USER_CONFIG_HOME/nebula-owner-demo"
COMPOSE_ENV="$RUNTIME_DIR/compose.env"
BACKEND_ENV="$RUNTIME_DIR/backend.env"
DUCKDNS_ENV="$RUNTIME_DIR/duckdns.env"
DUCKDNS_UPDATER="$RUNTIME_DIR/update-duckdns.sh"
ENV_FILE="$COMPOSE_ENV"

require_wsl_node() {
  local node_path npm_path node_major
  node_path=$(command -v node 2>/dev/null || true)
  npm_path=$(command -v npm 2>/dev/null || true)
  if [[ -z "$node_path" || -z "$npm_path" || "$node_path" == /mnt/c/* || "$npm_path" == /mnt/c/* ]]; then
    warn "A WSL-local Node installation is required; do not use /mnt/c Windows node/npm."
    open_url "https://nodejs.org/en/download"
    step "Install Node 24 LTS inside WSL. With nvm: nvm install 24 && nvm alias default 24 && nvm use 24."
    pause "Open a fresh WSL shell if needed, then press Enter to re-check."
    node_path=$(command -v node 2>/dev/null || true)
    npm_path=$(command -v npm 2>/dev/null || true)
  fi
  [[ -n "$node_path" && -n "$npm_path" && "$node_path" != /mnt/c/* && "$npm_path" != /mnt/c/* ]] \
    || { warn "Install WSL-local Node/npm, then re-run."; exit 1; }
  node_major=$(node -p 'process.versions.node.split(".")[0]')
  (( node_major == 24 )) || { warn "Select Node 24 LTS, then re-run."; exit 1; }
  node --version
  npm --version
}

require_reviewed_source_state() {
  local status_line status path unexpected=()
  while IFS= read -r status_line; do
    [[ -n "$status_line" ]] || continue
    status="${status_line:0:2}"
    path="${status_line:3}"
    case "$path" in
      frontend/vercel.json|docs/evidence/BE002_OWNER_OPERATED_DEMO_EVIDENCE.md) ;;
      *) unexpected+=("$status $path") ;;
    esac
  done < <(git -C "$REPO_ROOT" status --porcelain -- backend frontend deploy/oci docs/adr docs/research docs/runbooks/OWNER_OPERATED_DEMO_HOST.md docs/BE002_COMPLETION_REPORT.md docs/POST_PHASE3_SUB_TICKETS.md docs/DEVELOPMENT_PLAN.md docs/MASTER_PRD.md docs/NEBULA_PRD_v3.1.md README.md scripts/be002_owner_operated_demo_wizard.sh)
  if (( ${#unexpected[@]} )); then
    warn "Reviewed deployment sources are not committed; temporary deployment is intentionally blocked."
    for status_line in "${unexpected[@]}"; do note "  $status_line"; done
    step "Ask the agent to review and commit the owner-operated demo-host change, then re-run."
    exit 1
  fi
}

compose() {
  docker compose --project-name "$COMPOSE_PROJECT" --env-file "$COMPOSE_ENV" -f "$OCI_COMPOSE" "$@"
}

write_vercel_config() {
  local config_path="$FRONTEND_DIR/vercel.json"
  if [[ -f "$config_path" ]] && ! confirm "Replace frontend/vercel.json with the owner-operated demo routing config"; then
    note "The existing file must still pass exact semantic validation."
    return 0
  fi
  printf '%s\n' \
    '{' \
    '  "$schema": "https://openapi.vercel.sh/vercel.json",' \
    '  "rewrites": [' \
    '    {' \
    '      "source": "/api/v1/:path*",' \
    "      \"destination\": \"${BACKEND_ORIGIN}/v1/:path*\"" \
    '    },' \
    '    { "source": "/(.*)", "destination": "/index.html" }' \
    '  ],' \
    '  "headers": [' \
    '    {' \
    '      "source": "/api/v1/:path*",' \
    '      "headers": [' \
    '        { "key": "x-vercel-enable-rewrite-caching", "value": "0" }' \
    '      ]' \
    '    }' \
    '  ]' \
    '}' > "$config_path"
  note "Wrote public routing config: $config_path"
}

validate_vercel_config() {
  BACKEND_ORIGIN="$BACKEND_ORIGIN" node - "$FRONTEND_DIR/vercel.json" <<'NODE'
const fs = require('fs')
const config = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'))
const api = config.rewrites?.[0]
const spa = config.rewrites?.[1]
const apiHeaders = config.headers?.find((entry) => entry.source === '/api/v1/:path*')
const cacheOff = apiHeaders?.headers?.some(
  (entry) => entry.key?.toLowerCase() === 'x-vercel-enable-rewrite-caching' && entry.value === '0',
)
if (
  config.rewrites?.length !== 2
  || config.headers?.length !== 1
  || api?.source !== '/api/v1/:path*'
  || api?.destination !== `${process.env.BACKEND_ORIGIN}/v1/:path*`
  || spa?.source !== '/(.*)'
  || spa?.destination !== '/index.html'
  || apiHeaders?.headers?.length !== 1
  || !cacheOff
) {
  console.error('vercel.json does not match the reviewed owner-operated rewrite and cache policy')
  process.exit(1)
}
NODE
}

write_duckdns_updater() {
  printf 'DUCKDNS_DOMAIN=%q\nDUCKDNS_TOKEN=%q\n' "$DUCKDNS_DOMAIN" "$DUCKDNS_TOKEN" > "$DUCKDNS_ENV"
  chmod 600 "$DUCKDNS_ENV"
  cat > "$DUCKDNS_UPDATER" <<'SCRIPT'
#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=/dev/null
source "$SCRIPT_DIR/duckdns.env"
[[ -n "$DUCKDNS_DOMAIN" && -n "$DUCKDNS_TOKEN" ]] \
  || { printf 'Missing local DuckDNS configuration.\n' >&2; exit 1; }
urlencode() {
  local value="$1" encoded="" character ordinal index
  local LC_ALL=C
  for ((index = 0; index < ${#value}; index++)); do
    character="${value:index:1}"
    case "$character" in
      [a-zA-Z0-9.~_-]) encoded+="$character" ;;
      *)
        printf -v ordinal '%d' "'$character"
        printf -v character '%%%02X' "$ordinal"
        encoded+="$character"
        ;;
    esac
  done
  printf '%s' "$encoded"
}
PUBLIC_IP="$(curl --fail --silent --show-error --max-time 15 https://api.ipify.org)"
[[ "$PUBLIC_IP" =~ ^([0-9]{1,3}\.){3}[0-9]{1,3}$ ]] \
  || { printf 'Could not determine a valid public IPv4 address.\n' >&2; exit 1; }
DOMAIN_ENCODED=$(urlencode "$DUCKDNS_DOMAIN")
TOKEN_ENCODED=$(urlencode "$DUCKDNS_TOKEN")
CURL_CONFIG="$(mktemp)"
trap 'rm -f -- "$CURL_CONFIG"' EXIT
chmod 600 "$CURL_CONFIG"
printf 'url = "https://www.duckdns.org/update?domains=%s&token=%s&ip=%s"\n' \
  "$DOMAIN_ENCODED" "$TOKEN_ENCODED" "$PUBLIC_IP" > "$CURL_CONFIG"
if ! RESPONSE=$(curl --fail --silent --show-error --config "$CURL_CONFIG"); then
  printf 'DuckDNS update request failed before a response. Check your network and try again.\n' >&2
  exit 1
fi
if [[ "$RESPONSE" != "OK" ]]; then
  printf 'DuckDNS rejected the update (response: %s). Check the copied token and subdomain.\n' "$RESPONSE" >&2
  exit 1
fi
printf 'DuckDNS updated to %s\n' "$PUBLIC_IP"
SCRIPT
  chmod 700 "$DUCKDNS_UPDATER"
}

install_user_duckdns_timer() {
  local user_unit_dir="$HOME/.config/systemd/user"
  mkdir -p "$user_unit_dir"
  cat > "$user_unit_dir/nebula-duckdns.service" <<EOF
[Unit]
Description=Update Nebula owner-operated demo DuckDNS record

[Service]
Type=oneshot
ExecStart=$DUCKDNS_UPDATER
EOF
  cat > "$user_unit_dir/nebula-duckdns.timer" <<'EOF'
[Unit]
Description=Periodically update Nebula owner-operated demo DuckDNS record

[Timer]
OnBootSec=1min
OnUnitActiveSec=5min
Persistent=true

[Install]
WantedBy=timers.target
EOF
  systemctl --user daemon-reload
  systemctl --user enable --now nebula-duckdns.timer
  systemctl --user status nebula-duckdns.timer --no-pager
}

banner "Nebula BE-002 owner-operated demo host"

stage "Local prerequisites and profile isolation"
say "This is a temporary demo route. It does not modify or replace the OCI profile."
require_reviewed_source_state
DEPLOY_COMMIT=$(git -C "$REPO_ROOT" rev-parse HEAD)
require_wsl_node
for required_tool in git curl openssl sha256sum docker getent; do
  command -v "$required_tool" >/dev/null 2>&1 \
    || { warn "$required_tool is required. Install it locally, then re-run."; exit 1; }
done
docker version >/dev/null || { warn "Docker Engine/Desktop is not running."; exit 1; }
docker compose version
[[ -f "$OCI_COMPOSE" ]] || { warn "Missing reviewed portable runtime at deploy/oci/compose.yaml."; exit 1; }
if command -v ss >/dev/null 2>&1 && ss -ltn '( sport = :80 or sport = :443 )' | grep -q LISTEN; then
  warn "A process already owns TCP 80 or 443. Stop it before this profile starts."
  ss -ltn '( sport = :80 or sport = :443 )'
  exit 1
fi
confirm "Install locked frontend dependencies and Playwright Chromium now" \
  || { warn "Local browser verification is required."; exit 0; }
(cd "$FRONTEND_DIR" && npm ci && npx playwright install --with-deps chromium)
confirm "Run frontend tests, build, lint, and high-severity audit gates now" \
  || { warn "All local gates are required."; exit 0; }
(cd "$FRONTEND_DIR" \
  && npm test \
  && npm run build \
  && npm run lint \
  && npm audit --omit=dev --audit-level=high \
  && npm audit --audit-level=high)

stage "Stable Vercel frontend origin"
say "The browser keeps using a same-origin Vercel rewrite; it never calls your home backend directly."
if ! command -v vercel >/dev/null 2>&1; then
  confirm "Install the current Vercel CLI globally with npm now" && npm install --global vercel
fi
command -v vercel >/dev/null 2>&1 || { warn "Vercel CLI is unavailable."; exit 1; }
vercel --version
open_url "https://vercel.com/dashboard"
step "Use only the free Hobby plan for personal, non-commercial testnet work."
confirm "Authenticate and link frontend/ to the intended free Hobby project now" \
  || { warn "A stable frontend origin is required."; exit 0; }
(cd "$FRONTEND_DIR" && vercel login && vercel link)
step "In Project Settings, set Root Directory=frontend, Framework=Vite, Build Command=npm run build, Output Directory=dist."
confirm "The project is Hobby, personal/non-commercial, and uses those exact build settings" \
  || { warn "Correct the Vercel project before deployment."; exit 0; }
if ! confirm "Does the project already have its stable production HTTPS domain"; then
  [[ ! -f "$FRONTEND_DIR/vercel.json" ]] \
    || { warn "A routing file already exists; have the agent review it before bootstrap."; exit 1; }
  confirm "Approve one bootstrap production deploy to allocate the stable free domain" \
    || { warn "A stable frontend origin is required."; exit 0; }
  (cd "$FRONTEND_DIR" && vercel --prod)
fi
ask FRONTEND_ORIGIN "Enter the stable Vercel HTTPS origin (no path or trailing slash):"
[[ "$FRONTEND_ORIGIN" =~ ^https://[a-zA-Z0-9.-]+$ ]] \
  || { warn "Enter one HTTPS origin with no path or trailing slash."; exit 1; }

stage "DuckDNS and home-network reachability"
say "Use DuckDNS plus your router's public port forwards. A Cloudflare Quick Tunnel is not a stable production hostname."
open_url "https://www.duckdns.org/"
step "Create one DuckDNS subdomain. Do not commit its token or paste it into chat."
ask BACKEND_HOSTNAME "Enter the full DuckDNS hostname (for example nebula-api.duckdns.org):"
[[ "$BACKEND_HOSTNAME" =~ ^[a-zA-Z0-9.-]+\.duckdns\.org$ ]] \
  || { warn "Use the exact DuckDNS hostname with no scheme or path."; exit 1; }
DUCKDNS_DOMAIN="${BACKEND_HOSTNAME%.duckdns.org}"
say "Manual token input is intentionally invisible. In Windows Terminal, use Ctrl+Shift+V (not Ctrl+V), then press Enter once."
if command -v powershell.exe >/dev/null 2>&1 \
  && confirm "Use the DuckDNS token currently copied in the Windows clipboard instead"; then
  DUCKDNS_TOKEN=$(powershell.exe -NoProfile -Command 'Get-Clipboard -Raw' | tr -d '\r\n') \
    || { warn "Could not read the Windows clipboard. Use the manual hidden-input option."; exit 1; }
else
  ask_secret DUCKDNS_TOKEN "Paste the DuckDNS token (stored only in your local mode-0600 config):"
fi
DUCKDNS_TOKEN="${DUCKDNS_TOKEN//$'\r'/}"
[[ -n "$DUCKDNS_TOKEN" ]] || { warn "DuckDNS token is required for dynamic-IP updates."; exit 1; }
mkdir -p "$RUNTIME_DIR"
chmod 700 "$RUNTIME_DIR"
write_duckdns_updater
"$DUCKDNS_UPDATER"
PUBLIC_IP=$(curl --fail --silent --show-error --max-time 15 https://api.ipify.org)
note "Detected public IPv4: $PUBLIC_IP"
step "In your router, reserve this laptop's LAN IPv4 via DHCP reservation."
step "Forward TCP 80 and TCP 443 from the router WAN to that reserved laptop IPv4. Do not forward port 8000."
step "Compare the router WAN IPv4 with the detected public IPv4. If they differ, you are behind CGNAT or double NAT; this DuckDNS route cannot work until your ISP/router gives you a public IPv4."
step "If using Windows/WSL + Docker Desktop, allow inbound TCP 80 and 443 through Windows Firewall to Docker Desktop."
step "Cloudflare Quick Tunnels are intentionally unsupported here: their random URLs are development-only. A named Cloudflare Tunnel needs a domain under your Cloudflare account and is a separate, later-reviewed alternative."
confirm "The router WAN IPv4 equals the detected public IPv4 and TCP 80/443 now forward only to this laptop" \
  || { warn "Fix public reachability before asking Caddy for a certificate."; exit 0; }
pause "Wait for DuckDNS propagation, then press Enter to verify it."
DNS_IP=$(getent ahostsv4 "$BACKEND_HOSTNAME" | awk 'NR==1 {print $1}')
[[ "$DNS_IP" == "$PUBLIC_IP" ]] \
  || { warn "DuckDNS does not resolve to the detected public IP yet. Wait, run $DUCKDNS_UPDATER, then re-run."; exit 1; }

stage "Supabase and local runtime secrets"
say "Secrets live only under your local user configuration directory, never in this repository or Vercel."
open_url "https://supabase.com/dashboard"
step "Create/select a Free project and copy its SSL direct PostgreSQL URL, or its session-pooler URL on port 5432 when direct IPv6 is unavailable."
step "URL-encode password special characters. Never use the transaction pooler on port 6543 without a separate compatibility review."
confirm "The database is a Supabase Free project within its published quotas" \
  || { warn "A Free PostgreSQL project is required."; exit 0; }
printf '  %sPaste the PostgreSQL URL (hidden; saved only locally):%s ' "$BOLD" "$RESET"
read -rs DATABASE_URL || true
printf '\n'
case "$DATABASE_URL" in
  postgresql+asyncpg://*) ;;
  postgresql://*) DATABASE_URL="postgresql+asyncpg://${DATABASE_URL#postgresql://}" ;;
  postgres://*) DATABASE_URL="postgresql+asyncpg://${DATABASE_URL#postgres://}" ;;
  *) warn "Expected a PostgreSQL URL."; unset DATABASE_URL; exit 1 ;;
esac
[[ -n "$DATABASE_URL" && "$DATABASE_URL" != *$'\n'* && "$DATABASE_URL" != *$'\r'* && "$DATABASE_URL" != *"'"* && "$DATABASE_URL" != *'$'* ]] \
  || { warn "URL contains unsafe env-file characters; URL-encode the password and re-run."; unset DATABASE_URL; exit 1; }
JWT_SECRET=$(openssl rand -hex 32)
umask 077
printf "DATABASE_URL='%s'\nJWT_SECRET='%s'\nFRONTEND_URL='%s'\nRUNNERS_ENABLED='false'\n" \
  "$DATABASE_URL" "$JWT_SECRET" "$FRONTEND_ORIGIN" > "$BACKEND_ENV"
printf 'BACKEND_HOSTNAME=%s\nBACKEND_ENV_FILE=%s\n' "$BACKEND_HOSTNAME" "$BACKEND_ENV" > "$COMPOSE_ENV"
chmod 600 "$BACKEND_ENV" "$COMPOSE_ENV"
unset DATABASE_URL JWT_SECRET DUCKDNS_TOKEN
note "Installed only secret names: $(cut -d= -f1 "$BACKEND_ENV" | paste -sd, -)"

stage "Start the isolated Docker runtime and obtain HTTPS"
say "The existing OCI Compose source is reused read-only as a portable runtime definition; this starts a separate local Compose project."
confirm "Build commit $DEPLOY_COMMIT, run Alembic, and start only API+Caddy now" \
  || { warn "Temporary deployment was not authorized."; exit 0; }
compose config --quiet
compose build api
compose run --rm --no-deps api uv run --no-sync alembic upgrade head
compose up -d api caddy
compose ps
[[ -z "$(compose --profile runners ps --services --filter status=running | grep '^runner-' || true)" ]] \
  || { warn "Runners must remain disabled for the scoped BE-002 deployment."; exit 1; }
BACKEND_ORIGIN="https://$BACKEND_HOSTNAME"
say "Caddy can obtain its certificate only after public DNS and TCP 80/443 forwarding are correct."
pause "Wait for public TLS issuance, then press Enter to run external health checks."
curl --fail --silent --show-error "$BACKEND_ORIGIN/live"; printf '\n'
curl --fail --silent --show-error "$BACKEND_ORIGIN/ready"; printf '\n'
note "FastAPI port 8000 remains Docker-internal; only Caddy exposes 80/443."

stage "Always-on behavior and safe operation"
say "This route works only while the laptop, Docker engine, internet, router forwarding, Supabase, and DuckDNS updater remain available."
if command -v systemctl >/dev/null 2>&1 && systemctl --user show-environment >/dev/null 2>&1; then
  confirm "Install and enable a user-level five-minute DuckDNS updater timer now" \
    && install_user_duckdns_timer
  step "Ensure Docker starts at boot. On Linux: enable the docker system service; on Docker Desktop: enable Start Docker Desktop when you log in."
else
  warn "A systemd user session is unavailable (common on WSL)."
  step "Configure the router's DuckDNS/DDNS updater if available; otherwise schedule $DUCKDNS_UPDATER every five minutes using Windows Task Scheduler or your OS scheduler."
  step "Configure Docker Desktop to start at login, do not allow the laptop to sleep while plugged in, and keep the WSL/Docker environment running during a demo."
fi
step "To stop this temporary profile without touching OCI: docker compose --project-name nebula-owner-demo --env-file $COMPOSE_ENV -f deploy/oci/compose.yaml down"
step "To return to OCI later: stop this profile, then run scripts/be002_production_auth_wizard.sh. That separate wizard will replace the public Vercel rewrite only after OCI HTTPS is verified."
confirm "The laptop is configured to stay awake during demos and the dynamic DNS updater has a persistent schedule" \
  || { warn "Do not call this an always-on demo until startup and DNS updates are reliable."; exit 0; }

stage "Vercel rewrite, browser smoke, and public evidence"
say "Publish the same-origin rewrite and exercise real secure-cookie behavior through the Vercel frontend."
write_vercel_config
validate_vercel_config
confirm "Deploy the final free Vercel frontend configuration now" \
  || { warn "Frontend deployment was not authorized."; exit 0; }
(cd "$FRONTEND_DIR" && vercel --prod)
curl --fail --silent --show-error --output /dev/null "$FRONTEND_ORIGIN"
open_url "$FRONTEND_ORIGIN"
say "The smoke uses an ephemeral in-memory wallet and never prints its private key, cookies, or access token."
confirm "Run the deployed Chromium browser-auth smoke now" \
  || { warn "The live browser smoke is required."; exit 0; }
(cd "$FRONTEND_DIR" && BE002_FRONTEND_ORIGIN="$FRONTEND_ORIGIN" npm run test:browser-auth)

CURRENT_COMMIT=$(git -C "$REPO_ROOT" rev-parse HEAD)
[[ "$CURRENT_COMMIT" == "$DEPLOY_COMMIT" ]] \
  || { warn "HEAD changed during deployment; refusing PASS evidence."; exit 1; }
require_reviewed_source_state
mkdir -p "$EVIDENCE_DIR"
VERCEL_PROJECT_ID=$(node -e 'const fs=require("fs");const p=process.argv[1];process.stdout.write(fs.existsSync(p)?JSON.parse(fs.readFileSync(p,"utf8")).projectId||"unknown":"unknown")' "$FRONTEND_DIR/.vercel/project.json")
VERCEL_ORG_ID=$(node -e 'const fs=require("fs");const p=process.argv[1];process.stdout.write(fs.existsSync(p)?JSON.parse(fs.readFileSync(p,"utf8")).orgId||"unknown":"unknown")' "$FRONTEND_DIR/.vercel/project.json")
{
  printf '# BE-002 owner-operated demo-host evidence\n\n'
  printf -- '- Result: PASS\n'
  printf -- '- Completed UTC: %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  printf -- '- Repository commit: `%s`\n' "$DEPLOY_COMMIT"
  printf -- '- Hosting profile: temporary owner-operated laptop; OCI remains the canonical target\n'
  printf -- '- Backend hostname: `%s`\n' "$BACKEND_HOSTNAME"
  printf -- '- Backend origin: %s\n' "$BACKEND_ORIGIN"
  printf -- '- Frontend origin: %s\n' "$FRONTEND_ORIGIN"
  printf -- '- Vercel project ID: `%s`\n' "$VERCEL_PROJECT_ID"
  printf -- '- Vercel organization ID: `%s`\n' "$VERCEL_ORG_ID"
  printf -- '- Compose project: `%s`\n' "$COMPOSE_PROJECT"
  printf -- '- Dockerfile SHA-256: `%s`\n' "$(sha256sum "$REPO_ROOT/backend/Dockerfile" | cut -d' ' -f1)"
  printf -- '- Compose SHA-256: `%s`\n' "$(sha256sum "$OCI_COMPOSE" | cut -d' ' -f1)"
  printf -- '- Checks: frontend test/build/lint/audits; migration; public HTTPS /live and /ready; deployed Playwright auth smoke\n'
  printf -- '- Runner profile: intentionally disabled for scoped BE-002 deployment\n'
} > "$EVIDENCE_FILE"
chmod 600 "$EVIDENCE_FILE"
note "Public-only evidence written to $EVIDENCE_FILE for review before commit."

finish
